# Persistent for the complete input: active = {}; next_id = 1.
def iou(a,b):
    x1=max(a[0],b[0]); y1=max(a[1],b[1]); x2=min(a[2],b[2]); y2=min(a[3],b[3])
    intersection=max(0,x2-x1)*max(0,y2-y1)
    aa=max(0,a[2]-a[0])*max(0,a[3]-a[1]); bb=max(0,b[2]-b[0])*max(0,b[3]-b[1])
    return intersection/(aa+bb-intersection) if aa+bb-intersection>0 else 0.0

def process(detection_record, frame_meta):
    global active, next_id
    detections=detection_record['detections']
    candidates=[]
    for tid, old in active.items():
        for j, det in enumerate(detections):
            if old['label']==det['label']:
                overlap=iou(old['box'],det['box'])
                if overlap>=parameters['match_iou']: candidates.append((overlap,tid,j))
    used_ids=set(); used_dets=set(); observed=[]
    for overlap,tid,j in sorted(candidates,key=lambda x:x[0],reverse=True):
        if tid in used_ids or j in used_dets: continue
        used_ids.add(tid); used_dets.add(j)
        det=detections[j]; old=active[tid]
        previous_center=old['center']
        center=((det['box'][0]+det['box'][2])/2,(det['box'][1]+det['box'][3])/2)
        active[tid]={'box':det['box'],'label':det['label'],'center':center,'last_seen':frame_meta['frame_index']}
        observed.append({**det,'track_id':tid,'center':center,'previous_center':previous_center})
    for j,det in enumerate(detections):
        if j in used_dets: continue
        tid=next_id; next_id+=1
        center=((det['box'][0]+det['box'][2])/2,(det['box'][1]+det['box'][3])/2)
        active[tid]={'box':det['box'],'label':det['label'],'center':center,'last_seen':frame_meta['frame_index']}
        observed.append({**det,'track_id':tid,'center':center,'previous_center':None})
    for tid in list(active):
        if frame_meta['frame_index']-active[tid]['last_seen']>parameters['max_missed_frames']: del active[tid]
    return {'frame_index':frame_meta['frame_index'],'timestamp_s':frame_meta['timestamp_s'],'width':detection_record['width'],'height':detection_record['height'],'detections':detections,'tracks':observed}

from collections import deque
# Persistent for entire stream: times={k:deque() for k in parameters['thresholds']}; was_active={k:False for k in parameters['thresholds']}.
def process(record):
    global times, was_active
    now=record['timestamp_s']; thresholds=parameters['thresholds']
    for event in record['crossings']:
        times[event['class']].append(event['timestamp_s'])
    rolling={}; active={}; alerts=[]
    for label,limit in thresholds.items():
        queue=times[label]
        while queue and queue[0] < now-parameters['window_seconds']: queue.popleft()
        rolling[label]=len(queue)
        active[label]=rolling[label]>=limit
        if active[label] and not was_active[label]:
            alerts.append({'type':'congestion','class':label,'rolling_count':rolling[label],'threshold':limit,'window_seconds':parameters['window_seconds'],'timestamp_s':now,'frame_index':record['frame_index']})
        was_active[label]=active[label]
    current={label:0 for label in thresholds}
    for track in record['tracks']: current[track['label']]+=1
    return {**record,'current_counts':current,'rolling_counts':rolling,'congestion_active':active,'alerts':alerts}

